function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function initialsOf(name){return name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();}
function tablet(){return DEVICES[state.device][0]>=600;}
