function profileHint(){return state.lang==='te'?'మీ చైల్డ్ ప్రొఫైల్ మార్చడానికి '+(tablet()?'ఫోటోను ట్యాప్ చేయండి':'మధ్యలో ఉన్న ఫోటోను పైకి లేదా కిందికి స్వైప్ చేయండి'):tablet()?'Tap the photo to switch student':'Swipe the center photo up or down to switch student';}
