spAcademics=function(){const rows=[['book','Class diary','What each class covered, day by day','__daysum'],['edit','Homework','Assignments and class homework to tick off','__homework'],['image','Class gallery','Photos from the class teacher','__gallery'],['library','Timetable','The week, day by day','__timetable'],['cap','Exams & Marks','Schedule and results','__exams'],['helpc','Quizzes','Scheduled quizzes and your results','__quizzes'],['calendar','Calendar','Terms, holidays and events','__calendar'],['chart','Attendance','Overall, by subject, day by day','__attendance'],['library','Course content','Syllabus, materials and online classes','__course']];return `<div class="body dashboard"><h2 class="disp">Academics</h2><div class="academic-grid">${rows.map(r=>menuTile(r[0],r[1],r[2],`push('${r[3]}')`)).join('')}</div></div>`;};
