function isoDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function dateAt(s){return new Date(s+'T12:00:00');}
function calendarMove(step){const d=dateAt(state.calFocus);if(state.calMode==='month')d.setDate(1),d.setMonth(d.getMonth()+step);else d.setDate(d.getDate()+step*(state.calMode==='week'?7:1));state.calFocus=isoDate(d);render();}
function calendarMarkup(diary=false){
  const focus=dateAt(state.calFocus),mode=diary?'month':state.calMode;
  const start=new Date(focus);if(mode==='month')start.setDate(1),start.setDate(1-start.getDay());else if(mode==='week')start.setDate(start.getDate()-start.getDay());
  const count=mode==='month'?42:mode==='week'?7:1;
  const summaries=daySummaries();const eventRows=CAL_EVENTS.filter(e=>e.profiles.includes(activeWard().id));
  return `<div class="cal-top"><button class="lnk" aria-label="Previous ${mode}" onclick="calendarMove(-1)">${icon('back')}</button><b>${focus.toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</b><button class="lnk" aria-label="Next ${mode}" onclick="calendarMove(1)">${icon('chevR')}</button></div>
    ${!diary?`<div class="chips">${['month','week','day'].map(m=>choice(m[0].toUpperCase()+m.slice(1),mode===m,`state.calMode='${m}';render()`)).join('')}<button class="lnk" onclick="state.calFocus=DEMO_TODAY;state.calSelected=DEMO_TODAY;render()">Today</button></div>`:''}
    <div class="cal-grid ${mode}">${mode!=='day'?['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="cal-label">${d}</div>`).join(''):''}${Array.from({length:count},(_,i)=>{
      const d=new Date(start);d.setDate(start.getDate()+i);const iso=isoDate(d);const available=summaries.some(s=>s.iso===iso);const es=eventRows.filter(e=>e.date===iso);
      return `<button class="cal-day ${d.getMonth()!==focus.getMonth()?'dim':''} ${iso===state.calSelected?'selected':''} ${iso===DEMO_TODAY?'today':''}" aria-label="${iso}${diary&&available?', summary available':''}" ${diary&&!available?'disabled':''} onclick="${diary?`state.dayIdx=${summaries.findIndex(s=>s.iso===iso)};state.sheet=null;render()`: `state.calSelected='${iso}';render()`}"><span>${mode==='day'?d.toLocaleDateString('en-IN',{weekday:'long',day:'numeric'}):d.getDate()}</span>${diary?available?'<span class="dot"></span>':'':es.map(e=>`<span class="event-mini">${e.title}</span>`).join('')}</button>`;
    }).join('')}</div>${diary?'<div class="hint">Highlighted days have a class summary. Select a day to open it.</div>':''}`;
}
calendarScreen=function(){const rows=CAL_EVENTS.filter(e=>e.profiles.includes(activeWard().id)&&e.date===state.calSelected);return `<div class="body calendar-body">${calendarMarkup()}<div class="card"><b>${dateAt(state.calSelected).toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'})}</b>${rows.map(e=>menuTile('calendar',e.title,e.time,"state.sheet='event';render()")).join('')||'<div class="empty-note">No events on this day.</div>'}</div></div>`;};
daySummaryScreen=function(){return latestOriginal.daySummaryScreen().replace('<b style="flex:1;text-align:center">',`<button class="lnk" aria-label="Choose summary date" onclick="state.calFocus=daySummaries()[state.dayIdx||0].iso;state.calMode='month';state.sheet='diary';render()">${icon('calendar')}</button><b style="flex:1;text-align:center">`);};
function feeDemandDetail(d){return `<div class="fee-pane"><div class="card"><b>${d.variant}</b><small>${activeWard().name}</small><b style="font-size:30px">${money(d.balance)}</b>${chip(d.overdue?'Overdue':'Due',d.overdue?TONE_BAD:'var(--app-primary)')}</div><div class="card"><button class="btn" onclick="state.sheet='payment';render()">${icon('wallet')} Pay fee</button><small>Online fee payment is not available in the app yet. Please contact the office for payment options.</small></div><div class="card"><b>Fee breakdown</b>${d.heads.map(h=>`<div class="row" style="justify-content:space-between"><span>${h[0]}</span><b>${money(h[1])}</b></div>`).join('')}<div class="row" style="justify-content:space-between"><span>Paid so far</span><b>${money(d.paid)}</b></div></div></div>`;}
function feeReceiptDetail(r){return `<div class="fee-pane"><div class="card"><b>${r.no}</b><small>${activeWard().name} · ${r.on}</small><b style="font-size:30px">${money(r.amount)}</b>${chip(r.pending?'Not final':'Paid',r.pending?TONE_WARN:TONE_OK)}<small>${r.variant} · ${r.mode}</small></div><div class="card"><button class="btn" onclick="downloadSampleReceipt('${r.id}')">${icon('doc')} Download receipt PDF</button><small>This preview downloads a clearly marked sample receipt.</small></div></div>`;}
function feeDetailMarkup(){const f=fees(),x=state.feeDetail;if(!x)return '<div class="card empty-note">Select a fee or receipt to view its details.</div>';const r=(x.kind==='demand'?f.demands:f.receipts).find(r=>r.id===x.id);return r?(x.kind==='demand'?feeDemandDetail(r):feeReceiptDetail(r)):'';}
function openFee(kind,id){state.feeDetail={kind,id};if(!tablet())push('__feedetail');else render();}
feesScreen=function(){const f=fees();const list=`<div class="body"><h2 class="disp">Fees</h2><div class="card"><div class="lbl">Outstanding</div><b style="font-size:32px">${money(f.summary.outstanding)}</b>${f.summary.outstanding>0?`<button class="btn" onclick="openFee('demand','${f.demands.find(d=>d.balance>0).id}')">Pay fee</button><small>Online fee payment is not available in the app yet. Please contact the office for payment options.</small>`:''}</div><div class="sechead">Due now</div>${f.demands.filter(d=>d.balance>0).map(d=>menuTile('wallet',d.variant,money(d.balance)+' · '+(d.overdue?'Overdue':'Due'),`openFee('demand','${d.id}')`)).join('')||'<div class="card empty-note">Nothing is due. Everything is settled.</div>'}<div class="sechead">Past payments</div>${f.receipts.map(r=>menuTile('doc',r.no,money(r.amount)+' · '+r.on,`openFee('receipt','${r.id}')`)).join('')}</div>`;return tablet()?`<div class="fee-layout">${list}${feeDetailMarkup()}</div>`:list;};
function downloadSampleReceipt(id){
  const r=fees().receipts.find(r=>r.id===id);if(!r)return;
  // Minimal valid PDF, with ASCII text and byte-accurate xref; never an institute-issued receipt.
  const lines=['UNIVERSEIT - SAMPLE RECEIPT','PROTOTYPE ONLY - NOT VALID FOR ACCOUNTING',currentName(),r.no,'Amount: INR '+r.amount,'Date: '+r.on,'Mode: '+r.mode];
  const esc=s=>s.replace(/[\\()]/g,'\\$&');const stream='BT /F1 14 Tf 50 790 Td '+lines.map((l,i)=>(i?'0 -30 Td ':'')+'('+esc(l)+') Tj').join('\n')+' ET';
  const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`];
  let pdf='%PDF-1.4\n',offsets=[0];objects.forEach((o,i)=>{offsets.push(pdf.length);pdf+=`${i+1} 0 obj\n${o}\nendobj\n`;});const xref=pdf.length;pdf+=`xref\n0 6\n0000000000 65535 f \n${offsets.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')}trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
  const url=URL.createObjectURL(new Blob([pdf],{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download=r.no+'-SAMPLE.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);
}
