sessionsClosed=function(){const live=sessionsForDate().filter(s=>s.state!=='CANCELLED');return [live.filter(s=>s.state==='CLOSED').length,live.length];};
function canCloseSession(s){return s.date<DEMO_TODAY||s.date===DEMO_TODAY&&s.to<=state.demoTime;}
closeSession=function(id){const s=session(id);if(!s||s.state==='CANCELLED')return;if(!canCloseSession(s)){toast('You can close this session after '+prettyTime(s.to));return;}if(!s.topic){toast('Set how far at least one syllabus item got before closing');return;}s.state='CLOSED';back();toast('Session closed — class summary updated');};
sessionsScreen=function(){const rows=sessionsForDate();return `<div class="body"><h2 class="disp">Sessions</h2><div class="card"><button class="btn sec" onclick="state.sheet='sessions';render()">${icon('calendar')} ${state.sessionDate===DEMO_TODAY?'Today':state.sessionDate} · Choose date</button><small>${SESSIONS.filter(s=>s.state==='OPEN').length} unclosed sessions across all dates</small></div>${rows.map(s=>menuTile(s.state==='CLOSED'?'tickdone':'library',s.subject+' · '+s.section,prettyTime(s.from)+'–'+prettyTime(s.to)+' · '+s.state,s.state==='CANCELLED'?"toast('Session cancelled')":`openSession('${s.id}')`)).join('')||'<div class="empty-note">No sessions planned on this day.</div>'}</div>`;};
sessionScreen=function(){const s=session(state.sessionId);return latestOriginal.sessionScreen().replace(`<button class="btn" onclick="closeSession('${s.id}')">`,`<button class="btn" ${canCloseSession(s)?'':'disabled'} onclick="closeSession('${s.id}')">`).replace('<div class="sechead">Close with the summary</div>',`${!canCloseSession(s)?`<div class="card">This session can be closed after ${prettyTime(s.to)}.</div>`:''}<div class="sechead">Close with the summary</div>`);};
teacherHome=function(){const today=SESSIONS.filter(s=>s.date===DEMO_TODAY&&s.state!=='CANCELLED'),done=today.filter(s=>s.state==='CLOSED').length;return `<div class="body dashboard"><h2 class="disp">Your day</h2><small>${today.length} sessions today · Ravi Kumar</small><div class="dashboard-columns"><div class="dashboard-column"><div class="card"><b style="font-size:30px">${done}/${today.length}</b><small>Sessions closed</small><button class="lnk" style="color:var(--app-primary);text-align:left" onclick="go('Sessions');state.sheet='sessions';render()">${SESSIONS.filter(s=>s.state==='OPEN').length} unclosed sessions · Choose date</button></div><div class="card"><b>Your class · 7-A</b><small>31 of 34 in today · 2 on leave</small>${chip('1 birthday today','var(--app-primary)')}</div>${menuTile('gift','Class birthdays','Today and upcoming this academic year',"push('__birthdays')")}${menuTile('image','Class gallery','Photos for 7-A’s families',"push('__gallery')")}<div class="row"><button class="card" style="flex:1;text-align:left;color:var(--app-text);font:inherit" onclick="go('Approvals')"><b style="font-size:28px">${STUDENT_LEAVE.filter(r=>r.status==='OPEN').length}</b><small>Approvals waiting</small></button><button class="card" style="flex:1;text-align:left;color:var(--app-text);font:inherit" onclick="go('Alerts')"><b style="font-size:28px">${alertsUnread()}</b><small>Unread alerts</small></button></div></div><div class="dashboard-column"><div class="sechead">Today’s sessions</div>${today.map(s=>menuTile('library',s.subject,prettyTime(s.from)+'–'+prettyTime(s.to)+' · '+s.section+' · Room '+s.room,`openSession('${s.id}')`)).join('')}<div class="sechead">Queues</div>${menuTile('ticket','Ticket queue','Open tickets you can answer',"push('__stafftickets')")}${menuTile('people','My mentees','The students you look after',"push('__mentees')")}${menuTile('calendar','Your HR','Your leave and the punch clock',"push('__myhr')")}</div></div></div>`;};
inboxScreen=function(){return latestOriginal.inboxScreen().replace('<div class="body" style="padding:0;gap:0">','<div class="body" style="padding:0;gap:0"><div style="padding:12px"><button class="btn" onclick="push(\'__newchat\')">'+icon('add')+' Start a conversation</button></div>');};
function startConversation(id){const people={p1:'Priya Raghavan',p2:'Mrs. Iyer',p3:'Transport office'};let c=CONVOS.find(c=>c.id==='new-'+id);if(!c){c={id:'new-'+id,title:people[id],subtitle:'Staff · Main campus',initials:initialsOf(people[id]),unread:0,last_at:'now',messages:[]};CONVOS.unshift(c);}openChat(c.id);}
function newChatScreen(){return `<div class="body"><div class="field"><label for="staff-search">Find staff</label><input id="staff-search" class="inp" placeholder="Search employees" oninput="filterStaff(this.value)"></div><div id="staff-results">${[['p1','Priya Raghavan','Academic coordinator'],['p2','Mrs. Iyer','Teacher'],['p3','Transport office','Transport team']].map(([id,n,r])=>`<div data-staff-name="${n.toLowerCase()}">${menuTile('person',n,r,`startConversation('${id}')`)}</div>`).join('')}</div></div>`;}
function filterStaff(q){document.querySelectorAll('[data-staff-name]').forEach(el=>el.hidden=!el.dataset.staffName.includes(q.toLowerCase()));}
function digitalIdScreen(){return `<div class="body"><div class="card id-card">${brandLogo()}<b>${brand().name}</b><div class="avatar">${initialsOf(currentName())}</div><b style="font-size:22px">${currentName()}</b><small>${isFamily(state.persona)?'Student · Class '+activeWard().klass:'Staff · Teacher'}</small><span class="id-number">DEMO-${isFamily(state.persona)?activeWard().id.toUpperCase():'STAFF'}</span><img class="qr-demo" src="assets/sample-qr.svg" alt="Sample Digital ID QR code"><small>Sample QR · Not valid for campus entry</small></div><div class="hint">The app refreshes its signed code automatically. This public preview uses a static sample.</div><button class="btn sec" onclick="state.sheet='idcancel';render()">Preview device-confirmation cancellation</button></div>`;}
function mediCareScreen(){return `<div class="body"><h2 class="disp">MediCare</h2><div class="card"><b>MediCare</b><p>No clinics are available for your profile. Ask the office to assign a clinic.</p><button class="btn sec" onclick="toast('No clinic assignment in this sample')">Try again</button></div></div>`;}
function continuityScreen(){return `<div class="body"><div class="card"><b>Continue next academic year?</b><small>The school has requested your confirmation for ${activeWard().name}.</small>${['Yes, continuing','Not continuing','Undecided'].map(v=>`<button class="btn sec" onclick="state.continuityAnswer='${v}';render()">${v}${state.continuityAnswer===v?' ✓':''}</button>`).join('')}</div></div>`;}
const LATEST_SCREENS={__digitalid:['Digital ID',digitalIdScreen],__medicare:['MediCare',mediCareScreen],__scanid:['Scan ID',()=>'<div class="body"><div class="card empty-note">Camera scanning is available on the device app. This preview does not request camera access.</div></div>'],__feedetail:['Fee details',()=>'<div class="body">'+feeDetailMarkup()+'</div>'],__newchat:['New conversation',newChatScreen],__continuity:['Next year',continuityScreen]};
const STUDENT_LEAVE=[{id:'leave1',profile:'w1',from:'2026-10-23',to:'2026-10-23',reason:'Medical appointment',status:'OPEN',remarks:''}];
const DEMO_TICKETS=[];
const QUIZ_ATTEMPTS={};
function quizzesScreen(){const handed=QUIZ_ATTEMPTS[activeWard().id]?.handed;return `<div class="body"><div class="card"><b>Mathematics checkpoint</b><small>Mathematics · 2 questions · 10 minutes</small>${chip(handed?'Handed in':'Open','var(--app-primary)')}<small>${handed?'Results are announced once the quiz closes.':'Available during the sample quiz window.'}</small>${!handed?'<button class="btn" onclick="push(\'__quizattempt\')">Start quiz</button>':''}</div><div class="card"><b>Science revision</b><small>10 questions · 20 minutes</small>${chip('Results out',TONE_OK)}<button class="btn sec" onclick="push('__quizresult')">View results</button></div></div>`;}
function quizAttemptScreen(){const q=QUIZ_ATTEMPTS[activeWard().id]||(QUIZ_ATTEMPTS[activeWard().id]={answers:{},handed:false});return `<div class="body"><div class="card"><b>Mathematics checkpoint</b><small>10:00 · Demo timer</small></div>${[['What is 6 × 7?',['36','42','48']],['Solve x + 5 = 12.',['5','7','17']]].map(([text,options],i)=>`<div class="card"><b>${i+1}. ${text}</b>${options.map((o,j)=>`<button class="btn ${q.answers[i]===j?'':'sec'}" onclick="QUIZ_ATTEMPTS[activeWard().id].answers[${i}]=${j};render()">${o}</button>`).join('')}</div>`).join('')}<button class="btn" onclick="state.sheet='quizhandin';render()">Hand in</button><small>Preview answers remain in this tab only.</small></div>`;}
function quizResultScreen(){return `<div class="body"><div class="card"><b>Science revision</b><b style="font-size:34px">8 / 10</b>${chip('80% · Rank 2 of 30',TONE_OK)}<small>8 right · 2 wrong · 0 blank</small></div><div class="sechead">Your answers</div><div class="card"><b>Which part of the plant absorbs water?</b><p>Roots</p>${chip('Correct',TONE_OK)}</div><div class="card"><b>At what temperature does water boil at sea level?</b><p>Your answer: 90°C</p><small>Correct answer: 100°C</small></div><small>Sample result, shown after the example quiz has closed.</small></div>`;}
function menteesScreen(){return `<div class="body"><h2 class="disp">My mentees</h2><small>The students you look after</small>${WARDS.map((w,i)=>menuTile('person',w.name,'Class '+w.klass+(i===0?' · Check-in overdue':''),`state.menteeId='${w.id}';push('__menteecard')`)).join('')}</div>`;}
const MENTOR_LOG={};
function menteeCardScreen(){const w=WARDS.find(w=>w.id===state.menteeId)||WARDS[0];return `<div class="body"><h2 class="disp">${w.name}</h2><small>Class ${w.klass}</small><div class="card"><div class="lbl">How they are doing</div><b>${w.id==='w1'?'88% attendance':'Nothing marked yet'}</b><small>No consecutive absences · No behaviour records</small></div><form class="card" onsubmit="event.preventDefault();saveMentorNote()"><b>Add a note</b><div class="field"><label for="mentor-note">What was discussed</label><textarea id="mentor-note" class="inp" required></textarea></div><button class="btn">Save note</button></form><div class="sechead">Your log</div>${(MENTOR_LOG[w.id]||[]).map(n=>'<div class="card">'+escapeHtml(n)+'</div>').join('')||'<div class="card empty-note">Nothing recorded yet.</div>'}</div>`;}
function saveMentorNote(){const id=state.menteeId||'w1',note=document.getElementById('mentor-note').value.trim();if(!note)return;(MENTOR_LOG[id]||(MENTOR_LOG[id]=[])).unshift(note);render();toast('Sample note saved');}
function staffTicketsScreen(){return `<div class="body"><h2 class="disp">Ticket queue</h2>${DEMO_TICKETS.map(t=>menuTile('ticket',escapeHtml(t.subject),PROFILE_NAMES[t.profile]+' · Open',`state.demoTicket='${t.id}';push('__ticket')`)).join('')}${sample().tickets.map(t=>menuTile('ticket',t[2],t[0]+' · '+t[3],"state.demoTicket=null;push('__ticket')")).join('')}</div>`;}
Object.assign(LATEST_SCREENS,{__quizzes:['Quizzes',quizzesScreen],__quizattempt:['Mathematics checkpoint',quizAttemptScreen],__quizresult:['Science revision',quizResultScreen],__mentees:['My mentees',menteesScreen],__menteecard:['Mentee',menteeCardScreen],__stafftickets:['Ticket queue',staffTicketsScreen]});
function newTicketScreen(){return `<div class="body"><form class="card" onsubmit="submitDemoTicket(event)"><div class="field"><label for="ticket-category">Category</label><select id="ticket-category" class="inp"><option>General</option><option>Fees</option><option>Transport</option><option>Academics</option></select></div><div class="field"><label for="ticket-subject">Subject</label><input id="ticket-subject" class="inp" required maxlength="120"></div><div class="field"><label for="ticket-body">Description</label><textarea id="ticket-body" class="inp" required maxlength="2000"></textarea></div><button class="btn" type="submit">Raise a ticket</button><small>Preview only — this request is kept in this browser tab.</small></form></div>`;}
LATEST_SCREENS.__newticket=['Raise a ticket',newTicketScreen];
function submitDemoTicket(e){e.preventDefault();const subject=document.getElementById('ticket-subject').value.trim(),body=document.getElementById('ticket-body').value.trim();if(!subject||!body)return;DEMO_TICKETS.unshift({id:'demo'+(DEMO_TICKETS.length+1),profile:activeWard().id,subject,body,category:document.getElementById('ticket-category').value});state.pushed='__tickets';render();toast('Sample ticket raised');}
ticketsScreen=function(){const rows=DEMO_TICKETS.filter(r=>r.profile===activeWard().id);return `<div class="body"><button class="btn" onclick="push('__newticket')">${icon('add')} Raise a ticket</button>${rows.map(r=>menuTile('ticket',escapeHtml(r.subject),escapeHtml(r.category)+' · Open',`state.demoTicket='${r.id}';push('__ticket')`)).join('')}${sample().tickets.map(t=>menuTile('ticket',t[2],t[0]+' · '+t[1]+' · '+t[3],"state.demoTicket=null;push('__ticket')")).join('')}${!rows.length&&!sample().tickets.length?'<div class="empty-note">No tickets yet. Raise one and the office will reply here.</div>':''}</div>`;};
const originalTicketThread=ticketThreadScreen;
ticketThreadScreen=function(){const t=DEMO_TICKETS.find(r=>r.id===state.demoTicket);return t?`<div class="body"><div class="card"><b>${escapeHtml(t.subject)}</b><small>${escapeHtml(t.category)} · Open</small><p>${escapeHtml(t.body)}</p><small>Waiting for the office to reply.</small></div></div>`:originalTicketThread();};
leaveScreen=function(){const rows=STUDENT_LEAVE.filter(r=>r.profile===activeWard().id);return `<div class="body"><form class="card" onsubmit="submitDemoLeave(event)"><b>Apply for leave</b><div class="row"><div class="field" style="flex:1"><label for="leave-from">First day</label><input class="inp" id="leave-from" type="date" value="2026-10-23" required></div><div class="field" style="flex:1"><label for="leave-to">Last day</label><input class="inp" id="leave-to" type="date" value="2026-10-23" required></div></div><div class="field"><label for="leave-reason">Reason</label><textarea class="inp" id="leave-reason" required></textarea></div><button class="btn">Send request</button></form><div class="sechead">Requests for ${activeWard().name.split(' ')[0]}</div>${rows.map(r=>`<div class="card"><b>${r.from} — ${r.to}</b><p>${escapeHtml(r.reason)}</p>${chip(r.status,r.status==='APPROVED'?TONE_OK:TONE_WARN)}${r.remarks?`<small>Teacher’s note: ${escapeHtml(r.remarks)}</small>`:''}${r.status==='OPEN'?`<button class="btn sec" onclick="withdrawDemoLeave('${r.id}')">Withdraw</button>`:''}</div>`).join('')}</div>`;};
function submitDemoLeave(e){e.preventDefault();const from=document.getElementById('leave-from').value,to=document.getElementById('leave-to').value,reason=document.getElementById('leave-reason').value.trim();if(to<from){toast('The last day is before the first day');return;}if(!reason)return;STUDENT_LEAVE.unshift({id:'leave'+(STUDENT_LEAVE.length+1),profile:activeWard().id,from,to,reason,status:'OPEN',remarks:''});render();toast('Sample leave sent to the class teacher');}
function withdrawDemoLeave(id){STUDENT_LEAVE.find(r=>r.id===id).status='WITHDRAWN';render();}
approvalsScreen=function(){const rows=STUDENT_LEAVE.filter(r=>r.status==='OPEN');return `<div class="body"><h2 class="disp">Approvals</h2><small>${rows.length} waiting</small>${rows.map(r=>`<div class="card"><b>${PROFILE_NAMES[r.profile]}</b><small>${r.from} — ${r.to}</small><p>${escapeHtml(r.reason)}</p><div class="row"><button class="btn" onclick="state.leaveDecision='${r.id}';state.sheet='approve';render()">Approve</button><button class="btn sec" onclick="state.leaveDecision='${r.id}';state.sheet='reject';render()">Reject</button></div></div>`).join('')||'<div class="card empty-note">Nothing waiting on you.</div>'}</div>`;};
function decideDemoLeave(approved){const r=STUDENT_LEAVE.find(r=>r.id===state.leaveDecision);if(!r)return;r.status=approved?'APPROVED':'REJECTED';r.remarks=document.getElementById('rejection-reason')?.value.trim()||'';ALERTS_FEED.unshift({id:'leave-alert-'+r.id,profile:r.profile,cat:'LEAVE',title:approved?'Leave approved':'Leave rejected',body:`Leave for ${r.from} — ${r.to}. ${r.remarks}`,at:'now',read:false});state.sheet=null;render();}
ICONS.qr='<path d="M3 3h6v6H3zM15 3h6v6h-6zM3 15h6v6H3zM15 15h3v3h3v3h-6zM12 12h3v3h-3zM18 12h3v3h-3z"/>';
ICONS.scan=ICONS.qr;
function launchPreview(){return `<div class="launch-preview">${brandLogo(true)}<h2>${brandTitle()}</h2><div class="loader-capsule">${state.institutionId==='xyz'?'<img src="assets/xyz-busy-v2.gif" alt="Loading">':'<div class="plain-loader" role="status" aria-label="Loading"></div>'}</div><button class="btn sec" onclick="state.view='app';render()">Open preview</button></div>`;}
function sheetMarkup(){
  if(!state.sheet)return '';
  let title='',body='',actions='<button class="btn sec" onclick="closeSheet()">Close</button>';
  if(state.sheet==='students'){title='Linked students';body=WARDS.map((w,i)=>menuTile('person',w.name,'Class '+w.klass,`selectStudent(${i})`)).join('');}
  if(state.sheet==='signout'){title='Sign out?';body='You will need to sign in again to access your institute.';actions='<button class="btn sec" onclick="closeSheet()">Cancel</button><button class="btn" onclick="finishSignOut()">Sign out</button>';}
  if(state.sheet==='diary'){title='Choose summary date';body=calendarMarkup(true);}
  if(state.sheet==='sessions'){title='Choose session date';body=[DEMO_TODAY,...BACKLOG.map(r=>r.date)].map(d=>menuTile('calendar',d,SESSIONS.filter(s=>s.date===d&&s.state==='OPEN').length+' unclosed sessions',`state.sessionDate='${d}';state.sheet=null;state.tab='Sessions';state.pushed=null;render()`)).join('');}
  if(state.sheet==='payment'){title='Pay fee';body='Online fee payment is not available in the app yet. Please contact the office for payment options.';}
  if(state.sheet==='event'){title='Calendar';body=CAL_EVENTS.filter(e=>e.date===state.calSelected&&e.profiles.includes(activeWard().id)).map(e=>`<div class="card"><b>${e.title}</b><small>${e.date} · ${e.time}</small></div>`).join('');}
  if(state.sheet==='idcancel'){title='Confirm your identity';body='The device normally asks for fingerprint or face confirmation.';actions='<button class="btn sec" onclick="state.sheet=null;back()">Cancel sign-in</button><button class="btn" onclick="closeSheet()">Continue preview</button>';}
  if(state.sheet==='approve'||state.sheet==='reject'){const reject=state.sheet==='reject';title=reject?'Reject this leave?':'Approve this leave?';const r=STUDENT_LEAVE.find(r=>r.id===state.leaveDecision);body=escapeHtml(PROFILE_NAMES[r.profile])+' · '+r.from+' — '+r.to+(reject?'<div class="field"><label for="rejection-reason">Reason for the family</label><textarea id="rejection-reason" class="inp"></textarea></div>':'');actions=`<button class="btn sec" onclick="closeSheet()">Cancel</button><button class="btn" onclick="decideDemoLeave(${!reject})">${reject?'Reject':'Approve'}</button>`;}
  if(state.sheet==='quizhandin'){title='Hand in?';body='You cannot change your answers afterward. Results are announced once the quiz closes.';actions='<button class="btn sec" onclick="closeSheet()">Not yet</button><button class="btn" onclick="QUIZ_ATTEMPTS[activeWard().id].handed=true;state.sheet=null;push(\'__quizzes\')">Hand in</button>';}
  return `<div class="sheet-shade"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="sheet-body"><h3 id="sheet-title">${title}</h3>${body}</div><div class="sheet-footer">${actions}</div></section></div>`;
}
back=function(){if(state.sheet){closeSheet();return;}if(state.pushed==='__feedetail'){state.pushed=null;state.tab='Fees';render();return;}if(state.pushed==='__newchat'){state.pushed='__inbox';render();return;}if(state.pushed==='__menteecard'){push('__mentees');return;}if(['__quizattempt','__quizresult'].includes(state.pushed)){push('__quizzes');return;}if(state.pushed==='__ticket'&&isStaff()){push('__stafftickets');return;}latestOriginal.back();};
// Keep a genuine editable password field when its visibility changes; never store credentials.
signInScreen=function(){return latestOriginal.signInScreen().replace('<div class="inp txt">Your mobile number</div>','<input class="inp" type="tel" autocomplete="off" placeholder="Demo mobile number" aria-label="Registered mobile">').replace('<div class="inp txt">Your password</div>',`<div class="inp"><input id="demo-password" type="${state.passwordVisible?'text':'password'}" autocomplete="off" placeholder="Demo password" aria-label="Password"><button class="lnk" type="button" aria-label="${state.passwordVisible?'Hide':'Show'} password" onclick="togglePassword()">${state.passwordVisible?'Hide':'Show'}</button></div>`).replace('Demo role (dev)','Preview persona').replace('New accounts are created by your institute. There is no sign-up here.','Interactive demo only. Do not enter a real password. Accounts are created by your institute.');};
function togglePassword(){state.passwordVisible=!state.passwordVisible;const input=document.getElementById('demo-password');input.type=state.passwordVisible?'text':'password';const btn=input.nextElementSibling;btn.textContent=state.passwordVisible?'Hide':'Show';btn.setAttribute('aria-label',btn.textContent+' password');}
function railMarkup(){return `<nav class="siderail" aria-label="Main navigation">${tabsFor(state.persona).map(t=>`<button class="tab ${state.tab===t.name?'selected':''}" aria-label="${t.label}" aria-current="${state.tab===t.name?'page':'false'}" onclick="go('${t.name}')">${t.center?`<div class="avatar">${initialsOf(currentName())}</div>`:icon(t.icon)}<span class="cap">${t.label}</span></button>`).join('')} ${isFamily(state.persona)?'<button class="tab" aria-label="Switch student" onclick="openStudentPicker()">'+icon('swap')+'<span class="cap">Switch</span></button>':''}</nav>`;}
const originalTabbar=tabbar;
tabbar=function(tabs){return originalTabbar(tabs).replace('>'+initialsOf(PERSONA_LABEL[state.persona])+'<','>'+initialsOf(currentName())+'<');};
render=function(){
  const screen=document.getElementById('screen');screen.classList.toggle('tablet',tablet());screen.classList.toggle('expanded',DEVICES[state.device][0]>=840);
  const dims=DEVICES[state.device];document.getElementById('phoneFit').style.setProperty('--device-w',dims[0]+'px');document.getElementById('phoneFit').style.setProperty('--device-h',dims[1]+'px');
  if(state.view==='launch'){applyPalette();document.getElementById('app').innerHTML=statusbar()+launchPreview();syncDeck();renderLiveTrip();return;}
  latestOriginal.render();
  const app=document.getElementById('app');
  if(state.view==='app'&&!state.minimizedSim){
    const head=app.querySelector('.appheader');if(head){const logo=head.querySelector('.logo');if(logo)logo.outerHTML=brandLogo();head.querySelector('.brandname').innerHTML=brandTitle();}
    const header=head||app.querySelector('.subhead');if(header&&isFamily(state.persona))header.insertAdjacentHTML('beforeend',`<button class="header-avatar" aria-label="Switch student, ${activeWard().name}" onclick="openStudentPicker()">${initialsOf(activeWard().name)}</button>`);
    const backButton=app.querySelector('.subhead .back');if(backButton){backButton.outerHTML=`<button class="back" onclick="back()" aria-label="Back to ${escapeHtml(state.tab)}">${icon('back')}<span>${escapeHtml(state.tab)}</span></button>`;}
    if(tablet()){app.querySelector('.tabbar')?.remove();app.insertAdjacentHTML('beforeend',railMarkup());}
    const summaryHeader=app.querySelector('.subhead .grow');if(state.pushed==='__daysum'&&summaryHeader)summaryHeader.textContent='Class diary';
    if(state.pushed==='__ticket'&&state.demoTicket&&summaryHeader)summaryHeader.textContent=DEMO_TICKETS.find(t=>t.id===state.demoTicket)?.subject||'Ticket';
    if(state.pushed==='__menteecard'&&summaryHeader)summaryHeader.textContent=PROFILE_NAMES[state.menteeId]||'Mentee';
  }
  screen.querySelector('.sheet-shade')?.remove();screen.insertAdjacentHTML('beforeend',sheetMarkup());
  if(state.sheet){const sheet=screen.querySelector('.sheet');sheet.querySelector('button')?.focus({preventScroll:true});}
};
wireAvatar=function(){const el=document.getElementById('avatarwrap');if(!el||!isFamily(state.persona))return;let start=null;el.addEventListener('pointerdown',e=>{start=e.clientY;avatarDragged=false;el.setPointerCapture(e.pointerId);});el.addEventListener('pointermove',e=>{if(start!==null&&Math.abs(e.clientY-start)>8)avatarDragged=true;});el.addEventListener('pointerup',e=>{if(start===null)return;const dy=e.clientY-start;start=null;if(Math.abs(dy)>18){avatarDragged=true;dy<0?prevWard():nextWard();}});el.addEventListener('pointercancel',()=>{start=null;});};
fitDevice=function(){const box=document.getElementById('phoneFit');if(!box)return;const [w,h]=DEVICES[state.device];const top=box.getBoundingClientRect().top;const stage=box.parentElement;const availableWidth=Math.min(window.innerWidth-20,document.body.classList.contains('nodeck')?window.innerWidth-32:window.innerWidth>=1000?window.innerWidth-560:window.innerWidth-32);stage.style.maxWidth=Math.max(240,availableWidth)+'px';const fit=Math.max(.15,Math.min(1,(window.innerHeight-top-24)/h,availableWidth/w));box.style.setProperty('--fit',fit.toFixed(4));};
