const originalSyncDeck=syncDeck;
syncDeck=function(){originalSyncDeck();document.querySelectorAll('[data-device]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.device===state.device)));document.getElementById('instNote').textContent='Institution branding stays selected across linked profiles. XYZ previews the latest mobile artwork.';document.querySelector('#deckMixed').innerHTML=optRow(!state.mixed,'One persona','Only the selected workspace.',"setMixed(false)")+optRow(state.mixed,'Student + Parent + Teacher','Three linked students and Ravi Kumar’s teacher profile.',"setMixed(true)");};
const originalRenderLiveTrip=renderLiveTrip;
renderLiveTrip=function(){if(state.pushed||state.sheet||(!isFamily(state.persona)&&state.persona!=='transportcrew')){const el=document.getElementById('livetrip');el.className='livetrip hidden';el.innerHTML='';return;}originalRenderLiveTrip();};
document.addEventListener('keydown',e=>{if(!state.sheet)return;if(e.key==='Escape'){e.stopImmediatePropagation();closeSheet();}if(e.key==='Tab'){const buttons=[...document.querySelectorAll('.sheet button:not([disabled]),.sheet input,.sheet textarea')];const first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
